) AS (
  VALUES 
    (732::BIGINT, 'El profe explica bien, pero la materia puede llegar a ser pesada.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2026-05-17T00:00:00+00:00'::TIMESTAMPTZ, 'd11a563d36846b94bb27ac08a2afe30c2aa51a91825dd7b2bfc2c8e1db525908'::TEXT, ARRAY[3260]::BIGINT[]),
    (732::BIGINT, 'El profesor es buena gente, eso nadie lo niega, pero las clases de este curso son pesadas y el las hace excesivamente teóricas y más pesadas aún. El curso está sumamente mal distribuido en cuanto a porcentajes y el ofrece puntos extra; NO los distribuye de forma justa y aveces ni los da.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2025-12-10T00:00:00+00:00'::TIMESTAMPTZ, '76e7dddc35b5b715473f99a8c27866c6f6604f8d11c9b159526f846659d44204'::TEXT, ARRAY[3285]::BIGINT[]),
    (732::BIGINT, 'Persona sumamente amable y pura vida, tranquilo. Aunque a tí no te interese la materia, se nota que el posee mucho conocimiento y le gusta lo que ensena. Sus exámenes hacen que uses tu conocoimiento y habilidades de investigación.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-10-01T00:00:00+00:00'::TIMESTAMPTZ, '0534760d274c7fdf5729397221deb3e5a8d77ce848f7a8f491e9842765f06a63'::TEXT, ARRAY[3265]::BIGINT[]),
    (732::BIGINT, 'No es un mal profe, para nada, simplemente sus clases pueden llegar a ser aburridas, el primer examen es un trabajo de investigación que toma su tiempo pero nada del otro mundo'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, '48b3b98678a6102c966bdadd743eb53818b538b101a1d2ca3b0481e54fd73725'::TEXT, ARRAY[3265]::BIGINT[]),
    (732::BIGINT, 'Es aburrido y simplón, no me parece un buen profesor'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador']::TEXT[], '2025-05-23T00:00:00+00:00'::TIMESTAMPTZ, '6d00ae72dcb201875d3bd60b92dd99019220121f6b04c84e764fa1c6e8f93b07'::TEXT, ARRAY[3285]::BIGINT[]),
    (732::BIGINT, 'Es un profe muy bueno. El curso es tranquilo y él pura vida.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes']::TEXT[], '2025-01-17T00:00:00+00:00'::TIMESTAMPTZ, '8a33776d9650b7637e229f6bae961f09df4ddae533cd35513793beebf3dae558'::TEXT, ARRAY[3285]::BIGINT[]),
    (732::BIGINT, 'Buen profe, bastante amable y explica de forma clara, se nota que conoce mucho del tema y que le gusta. La materia en sí en es un toque aburrida, repetitiva.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2024-11-14T00:00:00+00:00'::TIMESTAMPTZ, '8b883e02032eeb54033f4192739d063e53287f4f88e3a062b92a00119eefe7a5'::TEXT, ARRAY[3285]::BIGINT[]),
    (732::BIGINT, 'Es un buen profe, buena persona y conoce muchísimo sobre los temas que da. Sus clases pueden ser muy rápidas por la información recargada, pero es justo en los exámenes. Los exámenes son para la casa generalmente, y da puntos extra y perdona muchos reclamos. Buen profe!'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Exámenes retadores', 'Da crédito extra']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'c1e5817e154f892123833cc744c5fc292fdaaaeda3572a67e4088426dc019d82'::TEXT, ARRAY[3265]::BIGINT[]),
    (732::BIGINT, 'Es buena persona, pero no esta hecho para ser profesor.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-03-12T00:00:00+00:00'::TIMESTAMPTZ, '543f2d21723f801b8437b8b7512d7e687bb2dd0492cb4b97cbd46bace2d6a247'::TEXT, ARRAY[3260]::BIGINT[]),
    (732::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-03-09T00:00:00+00:00'::TIMESTAMPTZ, '40bfc1a07398879ffe4682099d56e1b4511a53005b8dbeac23817a7fcb853763'::TEXT, ARRAY[3260]::BIGINT[]),
    (732::BIGINT, 'El profe es muy chill y buena nota, pero no sé que tiene que a mi me cuesta entenderle y no es que la materia sea dificil. Dependiendo cuesta que conteste los correos. Los quices y expos no son complicadas y casi siempre pone 100, pero los examenes si pueden llegar a ser un toque enredados.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo']::TEXT[], '2023-12-05T00:00:00+00:00'::TIMESTAMPTZ, '5538985f9f7b78e842eb53460bd366d8125cc1e8c8c2afbaeeeba395ce8482bb'::TEXT, ARRAY[3260]::BIGINT[]),
    (732::BIGINT, 'Sus clases son aburridas y largas (también creo que es cuestión de la materia). Califica justo y da puntos extra. A veces las instrucciones son poco claras. No hacía quices.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2023-12-03T00:00:00+00:00'::TIMESTAMPTZ, '00dbba8e37cd4911c469dec55ef0f8ad3e61e4d72c8380c6b0070bc938067390'::TEXT, ARRAY[3285]::BIGINT[]),
    (732::BIGINT, 'Se siente que sus clases van muy rápido porque las carga demasiado de información la cual va explicando en desorden, es buena persona y amable para responder consultas, pero todas sus evaluaciones son difíciles.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-08-30T00:00:00+00:00'::TIMESTAMPTZ, '0a586eff0019b86b6f7390426ca8e6d8cd3fd3869c8344b85ab6679e9dfa83b7'::TEXT, ARRAY[3265]::BIGINT[]),
    (732::BIGINT, 'Sus clases son largas y aburridas, cuesta bastante ponerle atención, aunque no es tanto problema, sin embargo los exámenes son difíciles y califica duro, si las evaluaciones fueran acorde a la calidad de lo que enseña sería buen profesor.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2023-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'f120abefc0b8f592ff6e0abe0b7775fc551174b7d965aba5fd17998f5d47d72d'::TEXT, ARRAY[3266]::BIGINT[]),
    (732::BIGINT, 'Es un profe genial, se nota que le gusta lo que hace. Además que ayuda mucho al estudiante a mejorar como futuro profesional. Es un profe que siempre estará para unx y hace el curso sea muy llevadero y divertido'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-27T00:00:00+00:00'::TIMESTAMPTZ, '29c60c8c10d2e880d60f2b3cd51d75f622d7a268ce01fb6bfaaf196af7324c46'::TEXT, ARRAY[3266]::BIGINT[]),
    (732::BIGINT, 'Como persona es pura vida y relajado. Como profe le gustan las cosas bien hechas, pero es flexible. Dura bastante en calificar y subir las notas. El curso como tal demanda tiempo y son muchos trabajos grupales, pero las clases y las prácticas se disfrutan.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '6f0e81992b6b03b8b6947586662cdd167366df60ce0c502c3125a5c60bba3d6c'::TEXT, ARRAY[1979]::BIGINT[]),
    (732::BIGINT, 'Da muy buenas clases, se nota que le gustan los temas. A veces puede ir un poco rápido o desordenado, pero uno se acostumbra y basta con tomar apuntes de lo esencial. Los examenes pueden ser difíciles, pero a veces envía casos de estudio a la casa y es más sencillo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'b97c3d865f3a39468f2a99ac06c1bf163d9e14ba291afe353e81c83e68741c99'::TEXT, ARRAY[3265]::BIGINT[]),
    (732::BIGINT, 'muy buen profe, es un curso lindísimo y el profe siempre esta dispuesto a ayudar en lo que sea necesario. Todos los trabajos son en grupo y los exámenes si requieren de que uno se comprometa a estudiar.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '5ea2370093797a2864a1e0e729627b6046595575169733affa192e00e39c59ec'::TEXT, ARRAY[1979]::BIGINT[]),
    (732::BIGINT, 'Sus clases son largas y aburridas y las evaluaciones son difíciles y poco claras, reparte puntos extras según criterio propio, lo que beneficio a estudiantes que eran de su agradó.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, '37337909d1f1c3857da77e6d54c6240929b69427047eb954bceecb44f4605209'::TEXT, ARRAY[3285]::BIGINT[]),
    (732::BIGINT, 'Sus clases son aburridas, en los trabajos califica según le plazca y reparte puntos extra solo a los estudiantes que le agradan'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-06-09T00:00:00+00:00'::TIMESTAMPTZ, '100561afcff43e4a60cedd47aadfc947f1110706b028f4ee4261fc03a6733e2f'::TEXT, ARRAY[3285]::BIGINT[]),
    (732::BIGINT, 'Su clase es aburrida y no sabe explicar bien los temas, los puntos extra se los inventa de la nada y los reparte según su preferencia hacia ciertos estudiantes, ya que tiende a favorecer a determinadas personas según que tan bien le caigan, tuvo un pésimo diseño de proyecto final.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Clases largas']::TEXT[], '2023-05-01T00:00:00+00:00'::TIMESTAMPTZ, '39a943d0d6c3a23fb3cdbdb068295e1acca8921151d59f2002e16b5771585365'::TEXT, ARRAY[3285]::BIGINT[]),
    (732::BIGINT, 'El profe explica muy bien. Califica algo duro pero justo y siempre está abierto a consultas. Se dan puntos extra de manera justa para todos. Super recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'dcecc54e3ebea95c0a428e9001251e9ac880071ac379bc1619cecb39c6f5e9c2'::TEXT, ARRAY[3285]::BIGINT[]),
    (732::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2022-12-31T00:00:00+00:00'::TIMESTAMPTZ, '804260e4b103183130130c260bc300d5c7894678b8bff8ce71b6bd6ed93f63a2'::TEXT, ARRAY[3260]::BIGINT[]),
    (732::BIGINT, 'Súper buen profe. Aveces se enredaba al explicar y en las evaluaciones pero se preocupa por los estudiantes y es muy flexible para las asignaciones. Hace el curso fácil y no pesado. Da muy buena retroalimentación. Súper recomendado!!!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-12T00:00:00+00:00'::TIMESTAMPTZ, '1d5b187a3003f3ce9574e7600b7e8c18ffcc4dd899fcf1a4e6fa5a803af3afc0'::TEXT, ARRAY[3260]::BIGINT[]),
    (732::BIGINT, 'Súper buen profe, brinda demasiada ayuda y se nota que se interesa porque los estudiantes entiendan. Es flexible con las asignaciones.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2022-10-29T00:00:00+00:00'::TIMESTAMPTZ, '4bf856a6f8b6573b084ab0276d4a68abdc47da93c6e56c0ac4fd18c75083c100'::TEXT, ARRAY[3260]::BIGINT[]),
    (732::BIGINT, 'De los mejores profes que va a encontrar en la carrera. No dude en matricular con él cualquier curso. Es demasiado comprensivo, con él usted aprende de verdad sobre cualquier tema, y se adapta a la opinión del grupo para ayudar siempre.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Da crédito extra']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '3f64d533018c52d4c55c5bc5b34534cb632a8043cc389c6e5885ecdaff4799e2'::TEXT, ARRAY[3265]::BIGINT[]),
    (732::BIGINT, 'Las clases pueden volverse algo aburridas por el tipo de curso pero el profe explica muy bien y detalladamente. Me encantó que los exámenes fueron de investigación.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'ded5435d976e5ff41ea549a57f66564051b4aa0e8e2bf1cccd9f6b146646dbae'::TEXT, ARRAY[3265]::BIGINT[]),
    (732::BIGINT, 'La materia en veces es aburrida, pero se aprende bastante. El profe es super bueno y aparte de que siempre está dispuesto a ayudar al estudiante. Los examenes son fáciles y le gusta que el estudiante sepa investigar de forma adecuada. LO RECOMIENDO 100%.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases largas']::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, '49f9097978092df489da8af24296a006a4090f0464d97a9f99fa42b31400b862'::TEXT, ARRAY[3265]::BIGINT[]),
    (732::BIGINT, 'Excelente profesional, de forma virtual deja exámenes en grupo fáciles y se aprende mucho. La materia es aburrida pero el profe es muy simpático y hace la clase divertida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-15T00:00:00+00:00'::TIMESTAMPTZ, '74bb61350f16be59e1fb9dd96673d82c2d58704d047eb165521ba92972230f3d'::TEXT, ARRAY[3265]::BIGINT[]),
    (732::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'b4a8cfacc7720c9ea632da867ede9e37079af14d5bac6d45ba11ff7c3a6efdf4'::TEXT, ARRAY[3266]::BIGINT[]),
    (732::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '23f7ac3a4ba563a24557793696d00b37983d8507e1686055f9f42b05a336e0b0'::TEXT, ARRAY[3265]::BIGINT[]),
    (732::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-06T00:00:00+00:00'::TIMESTAMPTZ, 'b4d95956af73e4d13d2379cd63d8c70ac5072ba5aed9fb303ecb8efc6599cca3'::TEXT, ARRAY[3265]::BIGINT[]),
    (732::BIGINT, 'El profe es muy pura vida y lo ayuda a uno cuando necesita. Califica un poco duro los informes, pero los parciales y exámenes cortos son normales... :D'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo']::TEXT[], '2019-07-25T00:00:00+00:00'::TIMESTAMPTZ, 'e94612c6e8ba6ec59b95a19cd70fdb27787ec2b5c7c05cf21e1200509b86f6a8'::TEXT, ARRAY[3266]::BIGINT[]),
    (732::BIGINT, 'Excelente profesor, explica muy bien la clase y tiene buena disposición para aclarar dudas. Se interesa por el aprendizaje del estudiante. Sí lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-31T00:00:00+00:00'::TIMESTAMPTZ, '292a4b4481ef9e14a347cad91016fd093cefe0fb5363cbdfc557dee863cb424a'::TEXT, ARRAY[1979]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
